<?php
declare(strict_types=1);ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
if(empty($_SESSION['admin_id'])){http_response_code(401);echo json_encode(['ok'=>false]);exit;}
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false]);exit;}
$raw=(string)file_get_contents('php://input');$data=json_decode($raw,true);$endpoint=trim((string)($data['endpoint']??''));
if($endpoint===''||!filter_var($endpoint,FILTER_VALIDATE_URL)||!str_starts_with($endpoint,'https://')){http_response_code(422);echo json_encode(['ok'=>false]);exit;}
if(!file_exists(__DIR__.'/config.php')){http_response_code(503);echo json_encode(['ok'=>false]);exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);$hash=hash('sha256',$endpoint);$ua=mb_substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,250);$st=$pdo->prepare('INSERT INTO push_subscriptions(endpoint_hash,endpoint,admin_id,user_agent,created_at,last_success_at) VALUES(?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE endpoint=VALUES(endpoint),admin_id=VALUES(admin_id),user_agent=VALUES(user_agent),last_success_at=NOW()');$st->execute([$hash,$endpoint,(int)$_SESSION['admin_id'],$ua?:null]);echo json_encode(['ok'=>true]);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false]);}
